// --- Search ---
const searchEl = $("search");
searchEl.addEventListener("input", () => { query = searchEl.value.trim(); $("clearSearch").style.display = query ? "" : "none"; render(); });
$("clearSearch").addEventListener("click", () => { searchEl.value=""; query=""; $("clearSearch").style.display="none"; render(); searchEl.focus(); });
// --- Query language ---------------------------------------------------------
// Supports: plain words (case-insensitive substring across title/desc/note/url/tags),
// #tag (exact tag match), "exact phrase", AND / OR / NOT, parentheses, and
// implicit AND between adjacent terms. A quoted operator word is plain text.
function tokenize(s){
  const toks = []; let i = 0;
  while (i < s.length){
    const c = s[i];
    if (/\s/.test(c)) { i++; continue; }
    if (c === "(") { toks.push({k:"lp"}); i++; continue; }
    if (c === ")") { toks.push({k:"rp"}); i++; continue; }
    if (c === '"') {
      let j = i+1, buf = "";
      while (j < s.length && s[j] !== '"') { buf += s[j]; j++; }
      i = j + 1;
      if (buf.trim()) toks.push({k:"term", node:{t:"phrase", v:buf}});
      continue;
    }
    if (c === "#") {
      let j = i+1, buf = "";
      while (j < s.length && !/[\s()"]/.test(s[j])) { buf += s[j]; j++; }
      i = j;
      if (buf) toks.push({k:"term", node:{t:"tag", v:buf}});
      continue;
    }
    let j = i, buf = "";
    while (j < s.length && !/[\s()"]/.test(s[j])) { buf += s[j]; j++; }
    i = j;
    const up = buf.toUpperCase();
    if (up === "AND") toks.push({k:"and"});
    else if (up === "OR") toks.push({k:"or"});
    else if (up === "NOT") toks.push({k:"not"});
    else toks.push({k:"term", node:{t:"text", v:buf}});
  }
  return toks;
}
function parseQuery(str){
  const T = tokenize(str); let P = 0;
  const peek = () => T[P], eat = () => T[P++];
  function parseOr(){
    let left = parseAnd();
    while (peek() && peek().k === "or") { eat(); const r = parseAnd(); left = left ? {t:"or",a:left,b:r} : r; }
    return left;
  }
  function parseAnd(){
    let left = parseNot();
    while (peek() && (peek().k === "and" || peek().k === "term" || peek().k === "not" || peek().k === "lp")) {
      if (peek().k === "and") eat();
      const r = parseNot();
      left = left ? {t:"and",a:left,b:r} : r;
    }
    return left;
  }
  function parseNot(){
    if (peek() && peek().k === "not") { eat(); const n = parseNot(); return n ? {t:"not",n} : null; }
    return parseAtom();
  }
  function parseAtom(){
    const tk = peek(); if (!tk) return null;
    if (tk.k === "lp") { eat(); const e = parseOr(); if (peek() && peek().k === "rp") eat(); return e; }
    if (tk.k === "term") { eat(); return tk.node; }
    eat(); return parseAtom(); // skip stray operator/paren
  }
  return parseOr();
}
function fieldsOf(b){
  return { text: [b.title, b.desc, b.note, b.url, b.tags.join(" ")].join(" ").toLowerCase(),
           tags: b.tags.map(t => t.toLowerCase()) };
}
function evalNode(n, f){
  if (!n) return true;
  switch (n.t){
    case "text":   return f.text.includes(n.v.toLowerCase());
    case "phrase": return f.text.includes(n.v.toLowerCase());
    case "tag":    return f.tags.includes(n.v.toLowerCase());
    case "not":    return !evalNode(n.n, f);
    case "and":    return evalNode(n.a, f) && evalNode(n.b, f);
    case "or":     return evalNode(n.a, f) || evalNode(n.b, f);
  }
  return true;
}
function collectHi(n, neg, out){
  if (!n) return;
  if (n.t === "text" || n.t === "phrase") { if (!neg) out.text.push(n.v); return; }
  if (n.t === "tag") { if (!neg) out.tag.push(n.v); return; }
  if (n.t === "not") { collectHi(n.n, !neg, out); return; }
  if (n.t === "and" || n.t === "or") { collectHi(n.a, neg, out); collectHi(n.b, neg, out); }
}
function compileQuery(str){
  const q = str.trim();
  if (!q) return { empty:true, test:()=>true, hiText:[], hiTag:[] };
  let ast;
  try { ast = parseQuery(q); } catch(e){ ast = null; }
  if (!ast) return { empty:true, test:()=>true, hiText:[], hiTag:[] };
  const hi = { text:[], tag:[] }; collectHi(ast, false, hi);
  return { empty:false, test:b => evalNode(ast, fieldsOf(b)), hiText:hi.text, hiTag:hi.tag };
}
function highlight(text, terms){
  const s = esc(text);
  const parts = (terms||[]).filter(Boolean).map(t => t.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));
  if (!parts.length) return s;
  const re = new RegExp("(" + parts.join("|") + ")", "gi");
  return s.replace(re, "<mark>$1</mark>");
}

// --- Render ---
function esc(s){ return (s||"").replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }
function render() {
  const list = $("list");
  if (!bookmarks.length) {
    $("count").textContent = "";
    list.innerHTML = '<div class="empty"><div class="big">Nothing saved yet</div>Paste a link above and it will appear here, safe and findable.</div>';
    return;
  }
  const cq = compileQuery(query);
  const shown = cq.empty ? bookmarks : bookmarks.filter(b => cq.test(b));
  $("count").textContent = cq.empty ? `(${bookmarks.length})` : `(${shown.length} of ${bookmarks.length})`;
  if (!cq.empty && !shown.length) {
    list.innerHTML = `<div class="empty"><div class="big">No matches for “${esc(query)}”</div>Try different words — you can combine them with AND, OR, NOT, quotes for an exact phrase, and #tag for a specific tag.</div>`;
    return;
  }
  list.innerHTML = shown.map(b => {
    const m = b.meta;
    return `<div class="card">
      <div class="body">
        <div class="head">
          <span class="card-fav" data-fav="${esc(m.favUrl)}" style="background:${m.favColor}">${esc(m.favLetter)}</span>
          <p class="title"><a href="${esc(b.url)}" target="_blank" rel="noopener">${highlight(b.title, cq.hiText)}</a></p>
          ${b.readLater ? '<span class="rl-badge">Read later</span>' : ''}
        </div>
        <div class="url">${highlight(b.url, cq.hiText)}</div>
        ${b.desc ? `<p class="desc">${highlight(b.desc, cq.hiText)}</p>` : ""}
        ${b.note ? `<p class="note">📝 ${highlight(b.note, cq.hiText)}</p>` : ""}
        ${b.tags.length ? `<div class="tags">${b.tags.map(t => { const isTag = cq.hiTag.some(x => x.toLowerCase()===t.toLowerCase()); return `<span class="tag">#${isTag ? "<mark>"+esc(t)+"</mark>" : highlight(t, cq.hiText)}</span>`; }).join("")}</div>` : ""}
      </div>
      <div class="thumb" style="background:${m.previewGrad}">${esc(m.previewLabel)}</div>
    </div>`;
  }).join("");
  // upgrade favicons to real images where available
  list.querySelectorAll(".card-fav").forEach(el => {
    const img = new Image(); img.onload = () => { el.textContent=""; el.appendChild(img); }; img.src = el.dataset.fav;
  });
}

render();
document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
</html>

