// --- Simulated page-metadata lookup (prototype stand-in for real page reading) ---
const KNOWN = {
  "stripe.com": { title: "Stripe | Payment Processing Platform for the Internet",
    desc: "Stripe powers online payments for businesses of every size with a suite of developer-first APIs." },
  "figma.com": { title: "Figma: The Collaborative Interface Design Tool",
    desc: "Design, prototype, and gather feedback all in one place with Figma." },
  "nytimes.com": { title: "Breaking News, World News & Multimedia — The New York Times",
    desc: "Live news, investigations, opinion, photos and video from the reporters of The New York Times." },
  "css-tricks.com": { title: "A Complete Guide to Flexbox | CSS-Tricks",
    desc: "Our comprehensive guide to CSS flexbox layout, explaining everything about flexbox properties for parent and children." }
};
function hue(str){ let h=0; for(let i=0;i<str.length;i++) h=(h*31+str.charCodeAt(i))%360; return h; }
function simulateFetch(url) {
  let host = "", path = "";
  try { const u = new URL(url); host = u.hostname.replace(/^www\./,""); path = u.pathname; }
  catch { host = url.replace(/^https?:\/\//,"").split("/")[0]; }
  // Simulate a page whose details can't be read automatically.
  if (/broken|unreadable/.test(host) || /\.invalid$/.test(host) || /\/fail(\/|$)/.test(path)) {
    const h0 = hue(host || url);
    return { failed:true, host, title:"", desc:"",
      favLetter:(host||"?").charAt(0).toUpperCase(), favColor:`hsl(${h0} 15% 60%)`,
      favUrl:"", previewGrad:"repeating-linear-gradient(45deg,#e4e7ec,#e4e7ec 10px,#eef1f5 10px,#eef1f5 20px)",
      previewLabel:"no preview" };
  }
  let meta = KNOWN[host];
  if (!meta) {
    let slug = path.split("/").filter(Boolean).pop() || host;
    slug = decodeURIComponent(slug).replace(/[-_]+/g," ").replace(/\.\w+$/,"").trim();
    const cap = s => s.replace(/\b\w/g, c => c.toUpperCase());
    meta = { title: slug ? cap(slug) + " — " + host : host,
             desc: "Saved from " + host + ". (Description read from the page.)" };
  }
  const h = hue(host);
  return { ...meta, host,
    favLetter: host.charAt(0).toUpperCase(),
    favColor: `hsl(${h} 55% 48%)`,
    favUrl: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
    previewGrad: `linear-gradient(135deg, hsl(${h} 60% 52%), hsl(${(h+40)%360} 62% 42%))`,
    previewLabel: host };
}

function normalizeInput(raw){
  let s = (raw||"").trim();
  if (!s) return { ok:false, reason:"Enter a link first." };
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) {
    if (/\s/.test(s) || !/\./.test(s)) return { ok:false, reason:"That doesn't look like a link — check it and try again." };
    s = "https://" + s;
  }
  try { new URL(s); } catch { return { ok:false, reason:"That doesn't look like a link — check it and try again." }; }
  return { ok:true, url:s };
}
function normUrl(u){
  try { const x = new URL(u); return (x.hostname.replace(/^www\./,"") + x.pathname.replace(/\/$/,"") + x.search).toLowerCase(); }
  catch { return u.trim().replace(/\/$/,"").toLowerCase(); }
}

// --- State ---
function seed(url, title, desc, tags, note, readLater){
  const m = simulateFetch(url);
  return { url, title, desc, note: note||"", tags, readLater: !!readLater, meta: m };
}
// Pre-loaded sample bookmarks so retrieval can be tried without saving many by hand.
let bookmarks = [
  seed("https://css-tricks.com/snippets/css/a-guide-to-flexbox/",
    "A Complete Guide to Flexbox | CSS-Tricks",
    "Comprehensive guide to CSS flexbox layout and its properties.",
    ["css","layout","reference"], "The **diagrams** are the best cheat-sheet.\nKey bits:\n- `justify-content` for the main axis\n- `align-items` for the cross axis\nSee also the [MDN guide](https://developer.mozilla.org/).", true),
  seed("https://figma.com", "Figma: The Collaborative Interface Design Tool",
    "Design, prototype, and gather feedback all in one place.",
    ["design","tools"], "", false),
  seed("https://stripe.com", "Stripe | Payment Processing Platform for the Internet",
    "Developer-first APIs for online payments.",
    ["payments","api","reference"], "Check the billing docs before the project.", true),
  seed("https://www.nytimes.com/section/technology", "Technology — The New York Times",
    "Latest news and analysis on the tech industry.",
    ["news","reading"], "", false),
  seed("https://www.atlasobscura.com/articles/ancient-rome-walking-tour",
    "A Walking Tour of Ancient Rome",
    "An article tracing the streets and ruins of ancient Rome.",
    ["travel","article","history"], "For the trip planning.", true),
  seed("https://www.gutenberg.org/ebooks/731",
    "The History of the Decline and Fall of the Roman Empire",
    "Gibbon's classic book covering the fall of Rome.",
    ["history","book"], "", false),
  seed("https://arxiv.org/pdf/1706.03762.pdf",
    "Attention Is All You Need (PDF)",
    "The paper introducing the Transformer architecture.",
    ["ml","paper","reading"], "Re-read section 3.2.", true)
];
// Give the samples spread-out "date added" values so sorting is demonstrable.
const _BASE = Date.parse("2026-09-24T12:00:00Z");
bookmarks.forEach((b, i) => b.addedAt = _BASE - i * 86400000);
// Pre-set a couple of preservation states for demonstration.
const _pre = t => bookmarks.find(b => b.title.startsWith(t));
if (_pre("Stripe")) { _pre("Stripe").preserved = { at: _BASE - 2*86400000, kind: "page" };
  _pre("Stripe").ia = { status: "done", at: _BASE - 2*86400000, url: "https://web.archive.org/web/2026*/https://stripe.com" }; }
if (_pre("Attention")) { _pre("Attention").preserved = { at: _BASE - 6*86400000, kind: "pdf" }; }
let pending = null;       // { url, meta }
let editIndex = -1;       // >=0 when editing an existing bookmark
let query = "";

const $ = id => document.getElementById(id);
$("fetchBtn").addEventListener("click", startCapture);
$("url").addEventListener("keydown", e => { if (e.key === "Enter") startCapture(); });
$("saveBtn").addEventListener("click", commitSave);
$("cancelBtn").addEventListener("click", resetCapture);
$("noteToolbar").querySelectorAll("button").forEach(btn => btn.addEventListener("click", () => formatNote(btn.dataset.fmt)));
$("settingsBtn").addEventListener("click", openSettings);
$("settingsClose").addEventListener("click", closeSettings);
$("settingsOverlay").addEventListener("click", e => { if (e.target === $("settingsOverlay")) closeSettings(); });
function openSettings(){ renderSettings(); $("settingsOverlay").style.display = "flex"; }
function closeSettings(){ $("settingsOverlay").style.display = "none"; }
function renderSettings(){
  $("setSort").innerHTML = SORT_OPTS.map(([v,l]) => `<option value="${v}"${sortMode===v?" selected":""}>${l}</option>`).join("");
  $("setSort").onchange = e => setSort(e.target.value);
  $("setPageSize").innerHTML = PAGE_OPTS.map(([v,l]) => `<option value="${v}"${pageSize===v?" selected":""}>${l}</option>`).join("");
  $("setPageSize").onchange = e => { pageSize = e.target.value; try { localStorage.setItem("bm.pagesize", pageSize); } catch(_){} visibleCount = pageLimit(); render(); };
  $("setTextSize").innerHTML = TEXT_OPTS.map(([v,l]) => `<button class="seg${textSize===v?" active":""}" data-ts="${v}">${l}</button>`).join("");
  $("setTextSize").querySelectorAll(".seg").forEach(b => b.onclick = () => { textSize = b.dataset.ts; try { localStorage.setItem("bm.textsize", textSize); } catch(_){} applyTextSize(); renderSettings(); });
}
$("exportBtn").addEventListener("click", exportBookmarks);
$("importBtn").addEventListener("click", () => $("importFile").click());
$("importFile").addEventListener("change", e => {
  const f = e.target.files[0]; if (!f) return;
  const r = new FileReader();
  r.onload = () => { const res = importBookmarksFromText(r.result); showIoMsg(`Imported ${res.added} bookmark${res.added===1?"":"s"}${res.dup?`, skipped ${res.dup} already saved`:""}`); };
  r.readAsText(f); e.target.value = "";
});

function allTags(){ const s = new Set(); bookmarks.forEach(b => b.tags.forEach(t => s.add(t))); return [...s].sort(); }

function startCapture() {
  const norm = normalizeInput($("url").value);
  if (!norm.ok) {
    $("urlError").textContent = "⚠ " + norm.reason;
    $("urlError").style.display = "";
    $("details").classList.remove("show");
    $("url").focus();
    return;
  }
  $("urlError").style.display = "none";
  const url = norm.url;
  const key = normUrl(url);
  const existing = bookmarks.findIndex(b => normUrl(b.url) === key);
  $("details").classList.remove("show");
  $("fetching").classList.add("show");
  $("fetchBtn").disabled = true;
  setTimeout(() => {
    if (existing >= 0) {
      openEdit(existing);
    } else {
      const meta = simulateFetch(url);
      pending = { url, meta }; editIndex = -1;
      fillForm({ url, title: meta.title, desc: meta.desc, tags: [], note: "", readLater: false, meta }, "new");
    }
    $("fetching").classList.remove("show");
    $("details").classList.add("show");
    $("fetchBtn").disabled = false;
    $("title").focus();
  }, 750);
}

function openEdit(i){
  const b = bookmarks[i];
  editIndex = i; pending = { url: b.url, meta: b.meta };
  fillForm(b, "dup");
}
function openEditByUrl(url){
  const key = normUrl(url); const i = bookmarks.findIndex(b => normUrl(b.url) === key); if (i < 0) return;
  editIndex = i; pending = { url: bookmarks[i].url, meta: bookmarks[i].meta };
  fillForm(bookmarks[i], "edit");
