// --- Simulated page-metadata lookup (prototype stand-in for real page reading) ---
const KNOWN = {
  "stripe.com": { title: "Stripe | Payment Processing Platform for the Internet",
    desc: "Stripe powers online payments for businesses of every size with a suite of developer-first APIs." },
  "figma.com": { title: "Figma: The Collaborative Interface Design Tool",
    desc: "Design, prototype, and gather feedback all in one place with Figma." },
  "nytimes.com": { title: "Breaking News, World News & Multimedia — The New York Times",
    desc: "Live news, investigations, opinion, photos and video from the reporters of The New York Times." },
  "css-tricks.com": { title: "A Complete Guide to Flexbox | CSS-Tricks",
    desc: "Our comprehensive guide to CSS flexbox layout, explaining everything about flexbox properties for parent and children." }
};
function hue(str){ let h=0; for(let i=0;i<str.length;i++) h=(h*31+str.charCodeAt(i))%360; return h; }
function simulateFetch(url) {
  let host = "", path = "";
  try { const u = new URL(url); host = u.hostname.replace(/^www\./,""); path = u.pathname; }
  catch { host = url.replace(/^https?:\/\//,"").split("/")[0]; }
  // Simulate a page whose details can't be read automatically.
  if (/broken|unreadable/.test(host) || /\.invalid$/.test(host) || /\/fail(\/|$)/.test(path)) {
    const h0 = hue(host || url);
    return { failed:true, host, title:"", desc:"",
      favLetter:(host||"?").charAt(0).toUpperCase(), favColor:`hsl(${h0} 15% 60%)`,
      favUrl:"", previewGrad:"repeating-linear-gradient(45deg,#e4e7ec,#e4e7ec 10px,#eef1f5 10px,#eef1f5 20px)",
      previewLabel:"no preview" };
  }
  let meta = KNOWN[host];
  if (!meta) {
    let slug = path.split("/").filter(Boolean).pop() || host;
    slug = decodeURIComponent(slug).replace(/[-_]+/g," ").replace(/\.\w+$/,"").trim();
    const cap = s => s.replace(/\b\w/g, c => c.toUpperCase());
    meta = { title: slug ? cap(slug) + " — " + host : host,
             desc: "Saved from " + host + ". (Description read from the page.)" };
  }
  const h = hue(host);
  return { ...meta, host,
    favLetter: host.charAt(0).toUpperCase(),
    favColor: `hsl(${h} 55% 48%)`,
    favUrl: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
    previewGrad: `linear-gradient(135deg, hsl(${h} 60% 52%), hsl(${(h+40)%360} 62% 42%))`,
    previewLabel: host };
}

function normalizeInput(raw){
  let s = (raw||"").trim();
  if (!s) return { ok:false, reason:"Enter a link first." };
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) {
    if (/\s/.test(s) || !/\./.test(s)) return { ok:false, reason:"That doesn't look like a link — check it and try again." };
    s = "https://" + s;
  }
  try { new URL(s); } catch { return { ok:false, reason:"That doesn't look like a link — check it and try again." }; }
  return { ok:true, url:s };
}
function normUrl(u){
  try { const x = new URL(u); return (x.hostname.replace(/^www\./,"") + x.pathname.replace(/\/$/,"") + x.search).toLowerCase(); }
  catch { return u.trim().replace(/\/$/,"").toLowerCase(); }
}

